mapper.select:
SELECT w.current_owner_user AS username, MAX(u.real_name) AS real_name, SUM(CASE WHEN w.status = 'PENDING' THEN 1 ELSE 0 END) AS pending, SUM(CASE WHEN w.status = 'RUNNING' THEN 1 ELSE 0 END) AS running, SUM(CASE WHEN w.status = 'WAITING_CHILD' THEN 1 ELSE 0 END) AS waiting_child, SUM(CASE WHEN w.status = 'SUSPENDED' THEN 1 ELSE 0 END) AS suspended, SUM(CASE WHEN w.status = 'CONCESSION_DONE' THEN 1 ELSE 0 END) AS concession_done, SUM(CASE WHEN w.status = 'WAITING_FIX' THEN 1 ELSE 0 END) AS waiting_fix, SUM(CASE WHEN w.status IN ('PENDING','RUNNING','WAITING_CHILD','SUSPENDED','CONCESSION_DONE') THEN 1 ELSE 0 END) AS active_count,
SUM(CASE WHEN w.status = 'DONE' THEN 1 ELSE 0 END) AS month_done,
SUM(CASE WHEN w.status = 'DONE' AND w.complete_time IS NOT NULL AND w.complete_time >= #{monthStart} AND w.complete_time < #{monthEnd} THEN 1 ELSE 0 END) AS month_done,
SUM(CASE WHEN w.status = 'PENDING' AND w.due_time IS NOT NULL AND w.due_time < #{now} THEN 1 ELSE 0 END) AS overdue_pending, SUM(CASE WHEN w.status = 'RUNNING' AND w.due_time IS NOT NULL AND w.due_time < #{now} THEN 1 ELSE 0 END) AS overdue_running, SUM(CASE WHEN w.status IN ('PENDING','RUNNING','WAITING_CHILD','SUSPENDED','CONCESSION_DONE') AND w.update_time < NOW() - INTERVAL #{staleDays} DAY THEN 1 ELSE 0 END) AS stale_count FROM work_order w LEFT JOIN sys_user u ON u.username = w.current_owner_user AND u.tenant_id = #{tenantId} AND u.deleted = 0 WHERE w.deleted = 0 AND w.tenant_id = #{tenantId}
AND w.task_type = #{taskType}
GROUP BY w.current_owner_user

SELECT
    w.id              AS id,
    w.task_no         AS task_no,
    w.title           AS title,
    w.current_owner_user AS current_owner_user,
    w.current_owner_name AS current_owner_name,
    w.due_time        AS due_time,
    DATEDIFF(#{now}, w.due_time) AS overdue_days
FROM work_order w
WHERE w.deleted = 0 AND w.tenant_id = #{tenantId}
  AND w.status = #{status}
  AND w.due_time IS NOT NULL AND w.due_time < #{now}

    AND w.task_type = #{taskType}



ORDER BY w.due_time ASC
LIMIT #{limit}

SELECT w.suspend_reason AS reason, COUNT(*) AS cnt FROM work_order w WHERE w.deleted = 0 AND w.tenant_id = #{tenantId} AND w.status = 'SUSPENDED'
AND w.task_type = #{taskType}
GROUP BY w.suspend_reason ORDER BY cnt DESC

SELECT w.id AS id, w.task_no AS task_no, w.title AS title, w.current_owner_user AS current_owner_user, w.current_owner_name AS current_owner_name, w.suspend_reason AS suspend_reason, w.suspend_remark AS suspend_remark, w.planned_resume_time AS planned_resume_time, CASE WHEN w.planned_resume_time IS NOT NULL AND w.planned_resume_time < #{now} THEN 1 ELSE 0 END AS resume_overdue FROM work_order w WHERE w.deleted = 0 AND w.tenant_id = #{tenantId} AND w.status = 'SUSPENDED'
AND w.task_type = #{taskType}
ORDER BY resume_overdue DESC, w.planned_resume_time ASC

