        AND w.status = 'PENDING' AND w.due_time IS NOT NULL AND w.due_time < #{now}


        AND w.status = 'RUNNING' AND w.due_time IS NOT NULL AND w.due_time < #{now}




            AND w.status = 'DONE'

                AND w.status = 'DONE' AND w.complete_time IS NOT NULL
                AND w.complete_time >= #{monthStart} AND w.complete_time < #{monthEnd}




        AND w.status IN ('PENDING','RUNNING','WAITING_CHILD','SUSPENDED','CONCESSION_DONE')
        AND w.update_time < NOW() - INTERVAL #{staleDays} DAY


